from __future__ import annotations

from procureai.agents.suite import agents as A
from procureai.agents.suite import packs as P
from procureai.agents.suite.base import AgentSpec

_RW = ("read", "write_results")
AGENTS: dict[str, AgentSpec] = {
    s.id: s
    for s in [
        AgentSpec("supervisor", "Supervisor Agent", "Orchestration", "Understands a request, picks the workflow, delegates to specialist agents in order, validates and consolidates results. Stops at human checkpoints.", A.supervisor_agent, (), ("read",), {"request": "text (required)"}, example="Analyze these vendor quotations"),
        AgentSpec("research", "Research Agent", "Knowledge", "Breaks a question into sub-questions, finds evidence for each in the project documents and reports what is missing.", A.research_agent, ("retrieve", "project_documents", "document_pages"), ("read",), {"question": "text (required)"}, example="What is the warranty requirement and who approves purchases above 50,000?", platform="knowledge"),
        AgentSpec("rag", "RAG Knowledge Agent", "Knowledge", "Hybrid (vector + BM25) retrieval with page citations; separates retrieved evidence from any AI interpretation.", A.rag_agent, ("retrieve",), ("read",), {"question": "text (required)", "top_k": "int (default 5)"}, example="What is the maximum delivery time allowed?", platform="knowledge"),
        AgentSpec("data_analyst", "Data Analyst Agent", "Business Intelligence", "Exploratory analysis of CSV/XLSX data: summary statistics, trends, IQR anomalies, correlations, charts, rule-based insights.", A.data_agent, ("project_documents", "load_dataframe"), ("read",), {"document_id": "optional dataset id"}, example="Analyze this dataset and generate insights", platform="finance"),
        AgentSpec("procurement", "Procurement Agent", "Procurement", "Extracts requirements and vendor quotations and runs the supervised LangGraph analysis (compliance + price + evidence). Pauses for human confirmation of requirements.", A.procurement_agent, ("run_procurement",), _RW, {"auto_confirm": "bool (default false)"}, writes=True, timeout_s=240, example="Analyze these vendor quotations", platform="procurement"),
        AgentSpec("vendor_intelligence", "Vendor Intelligence Agent", "Vendor Management", "Compares vendors using stored compliance and price results; computes a transparent risk score and indicators.", A.vendor_agent, ("latest_run", "compliance_rows", "price_rows"), ("read",), {}, example="Which vendor is the lowest risk?", platform="procurement"),
        AgentSpec("financial", "Financial Analysis Agent", "Financial Intelligence", "Budget vs actual variance by category, unusual spending, and quotation cost comparison.", A.financial_agent, ("project_documents", "load_dataframe", "latest_run", "price_rows"), ("read",), {"document_id": "optional"}, example="Compare the project budget with actual expenses", platform="finance"),
        AgentSpec("document_intelligence", "Document Intelligence Agent", "Document Intelligence", "Classification, extractive summaries, dates/amounts, missing-section checks and document comparison (PDF, DOCX, XLSX, CSV, TXT).", A.document_agent, ("project_documents", "document_pages"), ("read",), {"document_id": "optional", "compare_with": "optional document id"}, example="Summarize this company policy", platform="knowledge"),
        AgentSpec("report", "Report Generation Agent", "Reporting", "Generates PDF/Excel procurement reports or an executive summary of stored agent results.", A.report_agent, ("latest_run", "make_report", "recent_tasks"), ("read", "generate_files"), {"kind": "pdf | excel | summary"}, writes=True, example="Create a procurement report", platform="operations"),
        AgentSpec("workflow", "Workflow Automation Agent", "Automation", "Executes a saved workflow: ordered agent steps with approval checkpoints, retries and execution tracking.", A.workflow_agent, (), ("read",), {"workflow_id": "required"}, requires_project=False, writes=True, timeout_s=600, example="Run workflow 'Monthly contract review'"),
        AgentSpec("compliance", "Compliance Agent", "Compliance", "Explains compliance results with traceable evidence and lists what is missing or uncertain.", A.compliance_agent, ("latest_run", "compliance_rows", "open_review_items"), ("read",), {}, example="Which requirements are not met?", platform="procurement"),
        AgentSpec("communication", "Communication Agent", "Communication", "Drafts vendor follow-ups, meeting summaries and task updates for approval. Never sends anything.", A.communication_agent, ("latest_run", "compliance_rows", "recent_tasks", "recent_audit"), ("read",), {"kind": "vendor_followup | meeting_summary | task_update"}, requires_approval=True, example="Draft emails to vendors with missing information", platform="procurement"),
        AgentSpec("contract", "Contract Intelligence Agent", "Contract Intelligence", "Clause extraction, important dates, risk indicators, renewal reminders and contract comparison.", A.contract_agent, ("project_documents", "document_pages", "notify"), ("read", "notify"), {"document_id": "optional", "expiring_days": "int (default 60)"}, example="Find all contracts expiring in the next 60 days", platform="legal"),
        AgentSpec("resume_screener", "Resume Screening Agent", "HR & Recruitment", "Ranks resumes against a job description by must-have / nice-to-have skill coverage and experience, with evidence. Advisory only; ignores protected attributes.", P.resume_screener, ("project_documents", "document_pages"), ("read",), {"job_description_id": "optional", "must_have": "optional comma-separated skills"}, example="Shortlist candidates for this job description", platform="hr"),
        AgentSpec("ticket_triage", "Ticket Triage Agent", "Customer Support", "Categorises and prioritises support tickets (CSV/XLSX), scores sentiment and finds duplicates.", P.ticket_triage, ("project_documents", "load_dataframe"), ("read",), {"document_id": "optional"}, example="Triage the support tickets", platform="support"),
        AgentSpec("support_reply", "Support Reply Agent", "Customer Support", "Drafts a customer reply grounded in the knowledge base with citations. Draft only; a person must approve and send.", P.support_reply, ("retrieve",), ("read",), {"ticket": "text (required)"}, requires_approval=True, example="Customer asks: how do I get a refund for a duplicate charge?", platform="support"),
        AgentSpec("meeting_actions", "Meeting Actions Agent", "Operations", "Extracts action items with owners and due dates, decisions and open questions from meeting notes.", P.meeting_actions, ("project_documents", "document_pages"), ("read",), {"document_id": "optional"}, example="List action items from the meeting notes", platform="operations"),
        AgentSpec("risk_register", "Risk Register Agent", "Operations", "Scans project documents for risk statements, classifies them and drafts a risk register for humans to assess.", P.risk_register, ("project_documents", "document_pages"), ("read",), {"document_id": "optional"}, example="Identify project risks from the documents", platform="operations"),
    ]
}


def public_catalog() -> list[dict]:
    return [a.public() for a in AGENTS.values()]
